CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- 1. Table: carriers
DROP TABLE IF EXISTS local_charges CASCADE;
DROP TABLE IF EXISTS freight_rates CASCADE;
DROP TABLE IF EXISTS ports CASCADE;
DROP TABLE IF EXISTS carriers CASCADE;

CREATE TABLE carriers (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    code VARCHAR(50) UNIQUE NOT NULL,
    name VARCHAR(255) NOT NULL,
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 2. Table: ports
CREATE TABLE ports (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    port_name VARCHAR(150) NOT NULL,
    country VARCHAR(100) DEFAULT 'International',
    region VARCHAR(100) DEFAULT 'International',
    is_popular BOOLEAN DEFAULT FALSE,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 3. Table: freight_rates
CREATE TABLE freight_rates (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    carrier_id UUID NOT NULL REFERENCES carriers(id) ON DELETE CASCADE,
    port_id UUID REFERENCES ports(id) ON DELETE SET NULL,
    batch_id UUID,
    pol VARCHAR(100) NOT NULL,
    pod VARCHAR(150) NOT NULL,
    rate_20gp NUMERIC(10, 2) NOT NULL DEFAULT 0,
    rate_40gp NUMERIC(10, 2) NOT NULL DEFAULT 0,
    rate_40hq NUMERIC(10, 2) NOT NULL DEFAULT 0,
    rate_20rf NUMERIC(10, 2),
    rate_40rh NUMERIC(10, 2),
    currency VARCHAR(10) DEFAULT 'USD',
    service_name VARCHAR(150),
    routing_type VARCHAR(50) DEFAULT 'DIRECT',
    transit_time VARCHAR(100),
    frequency VARCHAR(100),
    valid_from DATE NOT NULL DEFAULT CURRENT_DATE,
    valid_to DATE NOT NULL DEFAULT (CURRENT_DATE + INTERVAL '30 days'),
    period_cycle VARCHAR(50) DEFAULT '1H',
    is_active BOOLEAN DEFAULT TRUE,
    remarks TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 4. Table: local_charges
CREATE TABLE local_charges (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    carrier_id UUID REFERENCES carriers(id) ON DELETE CASCADE,
    charge_code VARCHAR(50) NOT NULL,
    charge_name VARCHAR(150) NOT NULL,
    container_type VARCHAR(20) NOT NULL,
    amount NUMERIC(10, 2) NOT NULL,
    currency VARCHAR(10) DEFAULT 'THB',
    unit VARCHAR(50) DEFAULT 'CONTAINER',
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Indexes for lightning fast queries
CREATE INDEX idx_freight_rates_pod ON freight_rates(pod);
CREATE INDEX idx_freight_rates_carrier ON freight_rates(carrier_id);
CREATE INDEX idx_freight_rates_active ON freight_rates(is_active);
CREATE INDEX idx_ports_name ON ports(port_name);

